from pathlib import Path
import json,base64,io,html
from PIL import Image
R=Path(__file__).resolve().parents[2];E=R/'evidence/production';audit=json.loads((E/'R11-final-evidence-integrity.json').read_text());assert audit['status']=='PASS'
records=json.loads((E/'final-render-manifest.json').read_text());frames=json.loads((R/'design/production-views.json').read_text())['frames'];build=json.loads((E/'R11-native-build.json').read_text())
def image_uri(path,width=1200):
 with Image.open(path) as im:
  im=im.convert('RGB');im.thumbnail((width,10000));b=io.BytesIO();im.save(b,'JPEG',quality=82,optimize=True);return 'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
def esc(x):return html.escape(str(x),quote=True)
archives=[]
for name in ['R11-public-checkpoint.json','R11-additional-public-packages.json']:
 p=E/name
 if p.exists():archives+=json.loads(p.read_text()).get('archives',[])
links=''.join('<a class="download" target="_blank" rel="noopener" href="'+esc(a['url'])+'"><strong>'+esc(a['asset'])+'</strong><span>'+f"{a['bytes']/1048576:.1f} MB"+' · verified public ZIP</span></a>' for a in archives)
cards=[]
for f in frames:
 r=records[f['id']];group='town' if f['id'].startswith('H') else 'people' if f['id'].startswith('D') else 'floors';uri=image_uri(R/r['image'],1600 if group in ['town','people'] else 1200)
 cards.append('<article data-group="'+group+'" data-search="'+esc((f['id']+' '+f['title']+' '+f.get('programme','')).lower())+'"><button class="photo" onclick="show(this)"><img loading="lazy" src="'+uri+'" alt="'+esc(f['title'])+'"></button><div class="caption"><small>'+esc(f['id'])+' · '+str(r['dimensions'][0])+' × '+str(r['dimensions'][1])+' original</small><h3>'+esc(f['title'])+'</h3><p>'+esc(f.get('programme','Actual editable scene geometry, not generated imagery.'))+'</p><code>SHA256 '+r['final_sha256'][:20]+'…</code></div></article>')
hero=image_uri(R/records['H02']['image'],1800)
s='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Winterlichtplatz — editable Christmas square</title><style>*{box-sizing:border-box}body{margin:0;background:#101a21;color:#e7e8e4;font:15px/1.55 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:36px 5vw}header small{color:#d8be8b;letter-spacing:.16em;text-transform:uppercase}h1{font-family:Georgia,serif;font-size:clamp(42px,6vw,82px);font-weight:400;line-height:1.08;margin:18px 0}h2{font:400 32px Georgia,serif;margin-top:45px}p{color:#b9c2c6}a{color:#e1cda8}header p{max-width:820px;font-size:18px}.hero{display:block;width:100%;border-radius:8px;margin:24px 0}.stats{display:flex;gap:42px;flex-wrap:wrap;border-top:1px solid #34434a;border-bottom:1px solid #34434a;padding:22px 0}.stats strong{font:34px Georgia,serif;display:block}.stats span{color:#aeb9be}#downloads{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:12px}.download{display:block;background:#1b2a32;border:1px solid #34434a;padding:17px;text-decoration:none;border-radius:5px;overflow-wrap:anywhere}.download span{display:block;color:#aeb9be;font-size:12px}.note{padding:20px;background:#17252d;border-left:3px solid #d8be8b;margin:24px 0}.filters{display:flex;gap:9px;flex-wrap:wrap;position:sticky;top:0;background:#101a21ef;padding:16px 0;z-index:3}button,input{font:inherit;color:inherit;background:#22343e;border:1px solid #43555e;border-radius:4px;padding:8px 15px}button{cursor:pointer}input{min-width:240px;flex:1}#gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:22px}article{background:#17252d;overflow:hidden;border-radius:6px}.photo{padding:0;border:0;border-radius:0;width:100%;display:block;background:#27333c}.photo img{width:100%;display:block;aspect-ratio:16/9;object-fit:contain}.caption{padding:17px}.caption h3{font-size:17px;margin:6px 0}.caption p{font-size:13px;margin:7px 0}.caption small{color:#d8be8b}.caption code{font-size:11px;color:#879aa3}details{padding:20px 0;border-top:1px solid #34434a}summary{cursor:pointer}code{overflow-wrap:anywhere}dialog{background:#101a21;color:#eee;border:1px solid #567;max-width:95vw;max-height:95vh;padding:14px}dialog img{display:block;max-width:90vw;max-height:78vh;object-fit:contain}dialog::backdrop{background:#000d}.foot{margin:45px 0;color:#8fa2ab;font-size:12px} @media(max-width:500px){main{padding:25px 18px}#gallery{grid-template-columns:1fr}.stats{gap:20px}}</style><main><header><small>Original 3D environment · Winterlichtplatz</small><h1>A Christmas square,<br>inside and out.</h1><p>An editable Central European winter town with original fictional shops, furnished occupied floors, market stalls, public seating, trees, a playground and a licensed anatomical CG crowd.</p></header><img class="hero" src="HERO" alt="Actual rendered Winterlichtplatz Christmas tree and market"><div class="stats"><div><strong>12</strong><span>surrounding buildings</span></div><div><strong>26</strong><span>furnished floors /164 rooms</span></div><div><strong>36</strong><span>people /12 editable variants</span></div><div><strong>92</strong><span>producer-inspected originals</span></div></div><h2>Editable scene files</h2><p>Download the packed Blender native for the authored full-map materials and lighting. The static textured GLB is an engine-neutral derivative; separate full-map building files and editable person rigs are supplied. Archive links open the verified public files.</p><div id="downloads">DOWNLOADS</div><div class="note"><strong>Honest delivery scope</strong><p>These are generic licensed CG people, not twelve unique real-person scans. GLB uses a512px photographic texture budget and does not identically reproduce Blender HDRI, area lights, procedural microdetail, glass or colour management. The native retains the full source maps. Producer inspections and machine integrity checks are complete for these92 originals; independent non-owner acceptance is separate and is not self-awarded.</p></div><h2>Explore the actual renders</h2><p>Embedded images are lightweight viewing previews. Full native-pixel PNG originals, unaltered noisy provenance and per-frame source/hash records are in the render archive. Studio human images are labelled isolated asset inspections, not town-integration images.</p><div class="filters"><button onclick="filter('all')">All92</button><button onclick="filter('town')">Town6</button><button onclick="filter('floors')">Furnished floors78</button><button onclick="filter('people')">People8</button><input id="search" placeholder="Find B03, cafe, clinic, P01…" oninput="filter()"></div><section id="gallery">CARDS</section><h2>Open, inspect, edit</h2><details open><summary>Offline native view controls</summary><p>No add-on or network is needed to open the packed native. In Blender’s Text Editor, execute the embedded <code>VIEW_TOOLS.py</code>, then use <code>apply_view('B01_L01_interior')</code>, <code>apply_view('B01_L01_plan')</code> or <code>apply_view('B01_L01_cutaway')</code>. <code>apply_view('H02')</code> restores whole-town visibility. Technical cutaways intentionally hide high walls/ceilings; other-floor architecture is retained for enclosed interior views.</p><p>The assembled town/GLB crowd is static. Separate person natives retain editable anatomical armatures, clothing and authored poses; they are not live-linked to the static town crowd and are not certified animation-ready.</p></details><details><summary>Rights, provenance and technical limitations</summary><p>Project-authored geometry/layout/branding and original derivatives: CC0; project code: MIT. Poly Haven and used MakeHuman graphical assets: CC0, with original URL/author/byte/hash/notice evidence. MPFB build-time software GPL is separate from its graphical outputs. DejaVu/Bitstream Vera font notice included. Fictional marks are original compositions, not a promise of trademark clearance.</p><p>Native has the original1000m background horizon plus a redundant auxiliary500m plane; GLB omits the auxiliary plane and crops only the legacy horizon to112×100m snow context while retaining plaza, architecture, furnishings and people. Memory-only frame pruning/photographic resampling and standard colour-only OIDN are disclosed in per-frame records. No generative imagery or image-only room/people substitutes.</p><p>Conceptual architecture/playground visualization only: no structural/fire/accessibility/medical/playground certification, perfection claim or independent acceptance. Reproduction and actual inspection histories accompany the delivery.</p></details><div class="foot">Authoritative full-map native SHA256 <code>NATIVE</code><br>Blender4.3.2 · individual original-image reviews + exact-source integrity records · source <a href="https://github.com/dreamer2664/buildinglab/pull/6" target="_blank">production PR6</a></div></main><dialog id="lightbox"><button onclick="this.parentNode.close()">Close</button><p id="lighttitle"></p><img id="lightimage"><p>Viewing preview; full-resolution PNG and exact hash in render archive.</p></dialog><script>let group='all';function filter(g){if(g)group=g;let q=document.getElementById('search').value.toLowerCase();document.querySelectorAll('article').forEach(a=>a.hidden=!((group==='all'||a.dataset.group===group)&&a.dataset.search.includes(q)))}function show(b){document.getElementById('lightimage').src=b.querySelector('img').src;document.getElementById('lighttitle').textContent=b.nextElementSibling.querySelector('h3').textContent;document.getElementById('lightbox').showModal()}</script></html>'''
s=s.replace('HERO',hero).replace('DOWNLOADS',links).replace('CARDS',''.join(cards)).replace('NATIVE',build['full_resolution_native_sha256']);(R/'DELIVERY.html').write_text(s);print('FINAL_DELIVERY_GALLERY_WRITTEN',len(frames),'actual source images',len(s.encode()),'bytes')
